    titles = (
        db.query(Title)
        .order_by(Title.rating.desc().nullslast(), Title.id.asc())
        .limit(20)
        .all()
    )
    return [title_to_dict(t, db) for t in titles]


@router.get("top10")
def top10(kind: str | None = Query(None), db: Session = Depends(get_db), user=Depends(get_current_user)):
