/* ===== Fonts (provided assets) ===== */
@font-face {
  font-family: 'NetflixDisplay';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('/assets/fonts/display_anton_2.woff2') format('woff2'),
       url('/assets/fonts/display_anton_1.woff2') format('woff2'),
