}
@font-face {
  font-family: 'NetflixUI';
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url('/assets/fonts/ui_inter_6.woff2') format('woff2'),
       url('/assets/fonts/ui_inter_5.woff2') format('woff2'),
       url('/assets/fonts/ui_inter_0.woff2') format('woff2'),
       url('/assets/fonts/ui_inter_1.woff2') format('woff2'),
       url('/assets/fonts/ui_inter_2.woff2') format('woff2'),
       url('/assets/fonts/ui_inter_3.woff2') format('woff2'),
       url('/assets/fonts/ui_inter_4.woff2') format('woff2');
}

:root {
  --bg: #141414;
  --red: #e50914;
  --red-hover: #f6121d;
  --text: #ffffff;
  --text-dim: #e5e5e5;
  --text-dimmer: #b3b3b3;
  --text-muted: #808080;
  --panel: #181818;
  --border: #303030;
  --green: #46d369;
}

* { box-sizing: border-box; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font-family: 'NetflixUI', 'Helvetica Neue', Helvetica, Arial, sans-serif;
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
}
#root { min-height: 100vh; }
a { color: inherit; text-decoration: none; }
button { font-family: inherit; cursor: pointer; }
img { display: block; }
::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-track { background: transparent; }
::-webkit-scrollbar-thumb { background: #4d4d4d; border-radius: 4px; }

.display-font { font-family: 'NetflixDisplay', 'Helvetica Neue', Arial, sans-serif; letter-spacing: 0.5px; }

/* ===== Header ===== */
.nf-header {
  position: fixed; top: 0; left: 0; right: 0; z-index: 100;
  display: flex; align-items: center; gap: 24px;
  padding: 0 4vw; height: 68px;
  background: transparent;
  transition: background-color 0.4s ease, box-shadow 0.4s ease;
}
.nf-header.scrolled { background: #141414; box-shadow: 0 2px 12px rgba(0,0,0,0.5); }
.nf-header .wordmark { width: 111px; flex: 0 0 auto; display: flex; }
.nf-header .wordmark img { width: 100%; }
.nf-nav { display: flex; gap: 14px; align-items: center; }
.nf-nav a { font-size: 0.9rem; color: var(--text-dim); white-space: nowrap; padding: 4px 2px; }
.nf-nav a.active { color: #fff; font-weight: 600; }
.nf-nav a:hover { color: #e5e5e5; }
.nf-header-right { margin-left: auto; display: flex; align-items: center; gap: 18px; }
.icon-btn {
  background: none; border: none; color: #fff; padding: 6px; display: flex; align-items: center;
  border-radius: 50%;
}
.icon-btn:hover { background: rgba(255,255,255,0.15); }
.icon-btn svg { width: 22px; height: 22px; }

.search-wrap { position: relative; display: flex; align-items: center; }
.search-wrap.open { background: rgba(20,20,20,0.95); border: 1px solid #fff; }
.search-input {
  width: 0; border: none; background: transparent; color: #fff; outline: none; font-size: 0.9rem;
  transition: width 0.3s ease;
}
.search-wrap.open .search-input { width: 220px; margin-left: 4px; }
.search-results {
  position: absolute; top: 44px; left: -14px; width: 420px; max-height: 70vh; overflow-y: auto;
  background: rgba(20,20,20,0.97); border: 1px solid #303030; z-index: 200; padding: 8px 0;
}
.search-result-row { display: flex; gap: 12px; padding: 8px 14px; cursor: pointer; align-items: center; }
.search-result-row:hover { background: rgba(255,255,255,0.08); }
.search-result-row img { width: 64px; height: 38px; object-fit: cover; border-radius: 3px; }
.search-result-row .sr-name { font-size: 0.85rem; }
.search-result-row .sr-sub { font-size: 0.75rem; color: var(--text-muted); }

/* dropdowns */
.dropdown {
  position: absolute; top: 46px; min-width: 220px;
  background: rgba(20,20,20,0.97); border: 1px solid #303030; z-index: 200;
}
.dropdown.right { right: 0; }
.dropdown-item {
  display: flex; align-items: center; gap: 10px; width: 100%; text-align: left;
  padding: 10px 16px; font-size: 0.85rem; color: #fff; background: none; border: none;
}
.dropdown-item:hover { background: rgba(255,255,255,0.1); }
.dropdown-section { padding: 8px 16px 4px; font-size: 0.75rem; color: var(--text-muted); text-transform: uppercase; }
.dropdown-empty { padding: 18px 16px; font-size: 0.85rem; color: var(--text-dimmer); }
.dropdown-divider { border-top: 1px solid #303030; margin: 6px 0; }

.profile-menu { display: flex; align-items: center; gap: 6px; position: relative; }
.profile-avatar {
  width: 34px; height: 34px; border-radius: 4px; display: flex; align-items: center; justify-content: center;
  font-size: 1.1rem; cursor: pointer; background-size: cover;
}
.caret { width: 14px; height: 14px; transition: transform 0.2s; }
.caret.open { transform: rotate(180deg); }

/* ===== Hero / billboard ===== */
.hero {
  position: relative; height: 80vh; min-height: 480px;
  display: flex; align-items: flex-end;
  background-size: cover; background-position: center 20%;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background: linear-gradient(to right, rgba(20,20,20,0.92) 0%, rgba(20,20,20,0.55) 45%, rgba(20,20,20,0.1) 100%);
}
.hero::after {
  content: ''; position: absolute; left: 0; right: 0; bottom: 0; height: 160px;
  background: linear-gradient(to top, #141414 0%, rgba(20,20,20,0) 100%);
}
.hero-content { position: relative; z-index: 2; padding: 0 4vw 90px; max-width: 620px; }
.hero-title { font-family: 'NetflixDisplay', sans-serif; font-size: 3.6rem; line-height: 1; margin: 0 0 14px; text-transform: uppercase; }
.hero-meta { display: flex; align-items: center; gap: 10px; margin-bottom: 12px; }
.hero-synopsis { font-size: 1.05rem; line-height: 1.45; color: #e5e5e5; margin: 0 0 22px;
  display: -webkit-box; -webkit-line-clamp: 3; -webkit-box-orient: vertical; overflow: hidden; }
.hero-actions { display: flex; gap: 12px; align-items: center; }
.btn { display: inline-flex; align-items: center; gap: 10px; border: none; border-radius: 4px; font-size: 1.15rem; padding: 10px 26px; }
.btn svg { width: 26px; height: 26px; }
.btn-play { background: #fff; color: #000; }
.btn-play:hover { background: rgba(255,255,255,0.75); }
.btn-info { background: rgba(100,100,100,0.7); color: #fff; }
.btn-info:hover { background: rgba(60,60,60,0.6); }
.btn-red { background: var(--red); color: #fff; }
.btn-red:hover { background: var(--red-hover); }
.maturity-badge {
  border: 1px solid #737373; padding: 1px 7px; font-size: 0.8rem; color: #e5e5e5; margin-left: 4px;
}
.match { color: var(--green); font-weight: 600; font-size: 0.95rem; }
.hd-badge { border: 1px solid #737373; padding: 1px 5px; font-size: 0.7rem; color: #e5e5e5; }

/* ===== Rails ===== */
.rail { position: relative; padding: 18px 0 8px 4vw; margin-bottom: 14px; }
.rail-title { font-size: 1.35rem; font-weight: 600; margin: 0 0 10px; color: #e5e5e5; }
.rail-scroll { display: flex; gap: 8px; overflow-x: auto; scroll-behavior: smooth; padding-bottom: 12px; scrollbar-width: thin; }
.rail-scroll::-webkit-scrollbar { height: 4px; }
.rail-nav {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 30; width: 44px; height: 70%;
  background: rgba(20,20,20,0.7); border: none; color: #fff; display: none; align-items: center; justify-content: center;
}
.rail:hover .rail-nav { display: flex; }
.rail-nav.left { left: calc(4vw - 40px); }
.rail-nav.right { right: 8px; }
.rail-nav svg { width: 34px; height: 34px; }
.rail-empty { color: var(--text-muted); font-size: 0.95rem; padding: 24px 0; }

/* ===== Cards ===== */
.card { position: relative; flex: 0 0 auto; width: 168px; cursor: pointer; transition: transform 0.25s ease; }
.card-poster { width: 100%; aspect-ratio: 2 / 3; object-fit: cover; border-radius: 4px; background: #2f2f2f; }
.card:hover { transform: scale(1.06); z-index: 40; }
.card .card-hoverbar {
  position: absolute; left: 0; right: 0; bottom: 0; padding: 24px 10px 8px;
  background: linear-gradient(to top, rgba(0,0,0,0.9), rgba(0,0,0,0));
  display: flex; gap: 8px; opacity: 0; transition: opacity 0.2s;
}
.card:hover .card-hoverbar { opacity: 1; }
.mini-btn {
  width: 30px; height: 30px; border-radius: 50%; border: 1.5px solid rgba(255,255,255,0.5);
  background: rgba(42,42,42,0.75); color: #fff; display: flex; align-items: center; justify-content: center;
}
.mini-btn:hover { border-color: #fff; }
.mini-btn svg { width: 15px; height: 15px; }
.mini-btn.active { background: #fff; color: #000; }
.card .card-name { position: absolute; left: 0; right: 0; bottom: 0; padding: 20px 8px 6px;
  background: linear-gradient(to top, rgba(0,0,0,0.85), transparent); font-size: 0.8rem; text-align: center; }

/* hover preview (expanded) */
.hover-card {
  position: fixed; z-index: 300; width: 340px; background: #181818; border-radius: 6px;
  box-shadow: 0 8px 30px rgba(0,0,0,0.8); overflow: hidden;
}
.hover-card .hc-img { width: 100%; aspect-ratio: 16 / 9; object-fit: cover; }
.hover-card .hc-body { padding: 12px 14px 14px; }
.hc-actions { display: flex; gap: 8px; align-items: center; margin-bottom: 10px; }
.hc-meta { display: flex; align-items: center; gap: 8px; font-size: 0.8rem; margin-bottom: 6px; }
.hc-tags { font-size: 0.8rem; color: #cfcfcf; }
.hc-tags span:not(:last-child)::after { content: ' • '; color: #6b6b6b; }

/* ===== Top 10 rail ===== */
.top10-card { position: relative; flex: 0 0 auto; width: 210px; display: flex; cursor: pointer; }
.top10-card .num {
  font-family: 'NetflixDisplay', sans-serif; font-size: 7.5rem; line-height: 1; margin-right: -22px;
  color: #141414; -webkit-text-stroke: 2px #595959; z-index: 1; user-select: none;
}
.top10-card .card-poster { width: 128px; z-index: 2; }
.top10-card:hover .card-poster { filter: brightness(1.15); }

/* ===== Grid (my list / search / languages) ===== */
.grid-page { padding: 90px 4vw 40px; }
.grid-page h1 { font-size: 2rem; margin: 0 0 20px; }
.poster-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 8px; }
.grid-card { position: relative; }
.grid-card .card-name { position: static; background: none; padding: 8px 2px 0; font-size: 0.85rem; text-align: left; }
.grid-remove {
  position: absolute; top: 8px; right: 8px; z-index: 5; width: 28px; height: 28px; border-radius: 50%;
  border: none; background: rgba(20,20,20,0.8); color: #fff; display: flex; align-items: center; justify-content: center;
}
.grid-remove:hover { background: var(--red); }
.grid-remove svg { width: 14px; height: 14px; }
.progress-bar { position: absolute; left: 6%; right: 6%; bottom: 6%; height: 4px; background: #595959; border-radius: 2px; z-index: 4; }
.progress-bar > div { height: 100%; background: var(--red); border-radius: 2px; }

/* ===== Modal ===== */
.modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,0.7); z-index: 400; overflow-y: auto; }
.modal { position: relative; width: min(940px, 94vw); margin: 4vh auto 60px; background: #181818; border-radius: 6px 6px 0 0; }
.modal-backdrop { position: relative; width: 100%; aspect-ratio: 16 / 9; }
.modal-backdrop img { width: 100%; height: 100%; object-fit: cover; }
.modal-backdrop::after { content: ''; position: absolute; inset: 0; background: linear-gradient(to top, #181818 0%, rgba(24,24,24,0.2) 45%, rgba(24,24,24,0) 100%); }
.modal-close {
  position: absolute; top: 14px; right: 14px; z-index: 10; width: 38px; height: 38px; border-radius: 50%;
  background: #181818; border: none; color: #fff; display: flex; align-items: center; justify-content: center;
}
.modal-close svg { width: 20px; height: 20px; }
.modal-body { padding: 0 3vw 40px; margin-top: -120px; position: relative; z-index: 5; }
.modal-title { font-family: 'NetflixDisplay', sans-serif; font-size: 2.8rem; margin: 0 0 10px; text-transform: uppercase; line-height: 1.05; }
.modal-meta { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; font-size: 0.95rem; }
.modal-actions { display: flex; gap: 10px; align-items: center; margin-bottom: 18px; }
.round-btn {
  width: 42px; height: 42px; border-radius: 50%; border: 2px solid rgba(255,255,255,0.4);
  background: rgba(42,42,42,0.6); color: #fff; display: flex; align-items: center; justify-content: center;
}
.round-btn:hover { border-color: #fff; }
.round-btn.active { border-color: #fff; background: #fff; color: #000; }
.round-btn svg { width: 20px; height: 20px; }
.modal-synopsis { font-size: 1.02rem; line-height: 1.5; color: #e5e5e5; max-width: 720px; margin: 0 0 18px; }
.modal-genres { font-size: 0.9rem; color: #cfcfcf; margin-bottom: 26px; }
.modal-genres span:not(:last-child)::after { content: ' · '; color: #6b6b6b; }

/* episodes */
.episodes-header { display: flex; align-items: center; gap: 16px; margin-bottom: 10px; }
.episodes-header h2 { font-size: 1.5rem; margin: 0; flex: 1; }
.season-select { background: transparent; border: 1px solid #595959; color: #fff; padding: 8px 12px; font-size: 1rem; border-radius: 4px; }
.ep-row { display: grid; grid-template-columns: 190px 28px 1fr auto; gap: 14px; align-items: center; padding: 18px 10px; border-bottom: 1px solid #2f2f2f; cursor: pointer; }
.ep-row:hover { background: rgba(255,255,255,0.05); }
.ep-thumb { position: relative; width: 100%; aspect-ratio: 16 / 9; border-radius: 4px; overflow: hidden; background: #2f2f2f; }
.ep-thumb img { width: 100%; height: 100%; object-fit: cover; }
.ep-thumb .ep-play {
  position: absolute; right: 8px; bottom: 8px; width: 30px; height: 30px; border-radius: 50%;
  background: rgba(0,0,0,0.7); border: 1.5px solid rgba(255,255,255,0.6); color: #fff;
  display: flex; align-items: center; justify-content: center;
}
.ep-thumb .ep-play svg { width: 14px; height: 14px; }
.ep-num { font-size: 1.2rem; color: #707070; text-align: center; }
.ep-info h3 { margin: 0 0 6px; font-size: 0.95rem; font-weight: 500; }
.ep-info p { margin: 0; font-size: 0.82rem; color: #a3a3a3; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.ep-dur { color: #a3a3a3; font-size: 0.85rem; }
.ep-count { color: #a3a3a3; font-size: 0.9rem; margin-bottom: 6px; }

/* rate dialog */
.rate-dialog { position: fixed; inset: 0; z-index: 500; background: rgba(0,0,0,0.75); display: flex; align-items: center; justify-content: center; }
.rate-dialog-card { background: #232323; border-radius: 8px; padding: 28px 34px; width: 400px; text-align: center; position: relative; }
.rate-dialog-card h3 { margin: 0 0 6px; font-size: 1.15rem; }
.rate-dialog-card p { color: #a3a3a3; font-size: 0.9rem; margin: 0 0 20px; }
.rate-options { display: flex; justify-content: center; gap: 16px; }
.rate-opt {
  width: 64px; height: 64px; border-radius: 8px; border: 1.5px solid #4d4d4d; background: transparent; color: #fff;
  display: flex; align-items: center; justify-content: center;
}
.rate-opt:hover { border-color: #fff; background: rgba(255,255,255,0.06); }
.rate-opt.selected { border-color: #fff; background: rgba(255,255,255,0.12); }
.rate-opt svg { width: 30px; height: 30px; }
.rate-opt-label { font-size: 0.72rem; color: #a3a3a3; margin-top: 4px; }
.rate-close { position: absolute; top: 10px; right: 10px; }

/* ===== Player ===== */
.player-root { position: fixed; inset: 0; background: #000; z-index: 600; overflow: hidden; }
.player-root video { width: 100%; height: 100%; object-fit: contain; background: #000; }
.player-overlay { position: absolute; inset: 0; pointer-events: none; }
.player-title { position: absolute; top: 24px; left: 32px; font-size: 1.4rem; font-weight: 500; text-shadow: 0 1px 4px rgba(0,0,0,0.8); }
.player-back {
  position: absolute; top: 16px; left: 24px; z-index: 10; background: none; border: none; color: #fff; padding: 8px;
}
.player-back svg { width: 34px; height: 34px; }
.player-back.hidden { opacity: 0; }
.player-controls {
  position: absolute; left: 0; right: 0; bottom: 0; padding: 12px 24px 16px;
  background: linear-gradient(to top, rgba(0,0,0,0.9), rgba(0,0,0,0));
  transition: opacity 0.3s;
}
.player-controls.hidden { opacity: 0; }
.seek-row { display: flex; align-items: center; gap: 14px; margin-bottom: 8px; }
.seek { flex: 1; -webkit-appearance: none; appearance: none; height: 4px; border-radius: 2px; background: rgba(255,255,255,0.3); outline: none; cursor: pointer; }
.seek::-webkit-slider-thumb { -webkit-appearance: none; width: 14px; height: 14px; border-radius: 50%; background: var(--red); cursor: pointer; }
.seek::-moz-range-thumb { width: 14px; height: 14px; border-radius: 50%; background: var(--red); border: none; cursor: pointer; }
.seek-fill { position: relative; flex: 1; height: 4px; border-radius: 2px; background: rgba(255,255,255,0.3); cursor: pointer; }
.seek-fill > div { position: absolute; left: 0; top: 0; bottom: 0; background: var(--red); border-radius: 2px; }
.time-text { font-size: 0.85rem; color: #e5e5e5; min-width: 120px; text-align: right; }
.player-btn-row { display: flex; align-items: center; gap: 18px; }
.pbtn { background: none; border: none; color: #fff; padding: 4px; display: flex; align-items: center; }
.pbtn svg { width: 28px; height: 28px; }
.pbtn:hover svg { transform: scale(1.1); }
.vol-wrap { display: flex; align-items: center; gap: 8px; }
.vol { -webkit-appearance: none; appearance: none; width: 90px; height: 4px; border-radius: 2px; background: rgba(255,255,255,0.3); outline: none; cursor: pointer; }
.vol::-webkit-slider-thumb { -webkit-appearance: none; width: 12px; height: 12px; border-radius: 50%; background: #fff; }
.vol::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: #fff; border: none; }
.player-right { margin-left: auto; display: flex; align-items: center; gap: 16px; position: relative; }
.player-menu { position: absolute; bottom: 44px; right: 0; width: 220px; background: rgba(10,10,10,0.92); border: 1px solid #333; z-index: 20; }
.player-menu-title { padding: 10px 14px 4px; font-size: 0.75rem; color: #a3a3a3; text-transform: uppercase; }
.player-menu-item { display: flex; align-items: center; gap: 10px; width: 100%; text-align: left; padding: 9px 14px; background: none; border: none; color: #fff; font-size: 0.9rem; }
.player-menu-item:hover { background: rgba(255,255,255,0.08); }
.player-menu-item.selected { color: var(--red); }
.ep-drawer {
  position: absolute; top: 0; bottom: 0; right: 0; width: 440px; max-width: 90vw; background: rgba(10,10,10,0.96);
  z-index: 30; overflow-y: auto; border-left: 1px solid #333; padding: 16px;
}
.ep-drawer h3 { margin: 10px 0; font-size: 1.2rem; }

/* ===== Landing ===== */
.landing { position: relative; min-height: 100vh; display: flex; flex-direction: column; }
.landing-collage { position: absolute; inset: 0; z-index: 0; }
.landing-collage .collage-grid {
  position: absolute; inset: 0; display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: repeat(4, 1fr);
}
.landing-collage .collage-grid img { width: 100%; height: 100%; object-fit: cover; }
.landing-collage::after { content: ''; position: absolute; inset: 0; background: rgba(10,10,10,0.55); }
.landing-top { position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: center; padding: 20px 4vw; }
.landing-top .wordmark { width: 130px; }
.landing-top .sign-in { border: 1px solid #fff; color: #fff; background: none; padding: 8px 18px; font-size: 0.95rem; }
.landing-top .sign-in:hover { background: rgba(255,255,255,0.12); }
.landing-center { position: relative; z-index: 2; flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 0 20px; }
.landing-center .big-wordmark { width: min(420px, 60vw); margin-bottom: 26px; }
.landing-center h1 { font-size: clamp(1.8rem, 4vw, 3rem); margin: 0 0 22px; max-width: 800px; }
.landing-cta { display: flex; flex-direction: column; align-items: center; gap: 14px; }
.landing-email-row { display: flex; gap: 8px; }
.landing-email-row input {
  width: min(420px, 80vw); padding: 14px 18px; font-size: 1.05rem; background: rgba(38,38,38,0.75);
  border: 1px solid #555; color: #fff; outline: none;
}
.landing-email-row button {
  padding: 14px 26px; font-size: 1.1rem; background: var(--red); color: #fff; border: none;
  display: flex; align-items: center; gap: 8px;
}
.landing-email-row button:hover { background: var(--red-hover); }
.landing-fine { color: #999; font-size: 0.85rem; margin-top: 16px; }

/* ===== Login ===== */
.login-page { min-height: 100vh; display: flex; align-items: flex-start; justify-content: center; padding: 10vh 16px 60px; }
.login-card { width: 450px; max-width: 94vw; background: #fff; color: #000; border-radius: 4px; padding: 40px 34px; }
.login-card .wordmark { width: 118px; margin-bottom: 18px; }
.login-card h1 { font-size: 1.9rem; margin: 0 0 22px; font-weight: 400; }
.login-card .field { margin-bottom: 14px; }
.login-card input {
  width: 100%; padding: 15px 14px; font-size: 1rem; border: 1px solid #000; background: #fff; outline: none;
}
.login-card input:focus { border-width: 2px; }
.login-card .error { color: #b00020; font-size: 0.9rem; margin: 10px 0; }
.login-card .btn-signin {
  width: 100%; background: rgba(229,9,20,0.75); color: #fff; border: none; padding: 14px; font-size: 1.15rem; margin-top: 6px;
}
.login-card .btn-signin:hover { background: rgba(229,9,20,0.95); }
.login-card .alt { text-align: center; margin-top: 14px; font-size: 0.95rem; color: #4d4d4d; }
.login-card .alt a { color: #0075aa; cursor: pointer; }
.login-card .note { font-size: 0.75rem; color: #808080; margin-top: 22px; border-top: 1px solid #ddd; padding-top: 14px; }

/* ===== Profiles ===== */
.profiles-page { min-height: 100vh; display: flex; flex-direction: column; align-items: center; padding: 8vh 20px 40px; }
.profiles-top { width: 100%; display: flex; align-items: center; justify-content: space-between; margin-bottom: 50px; }
.profiles-top .wordmark { width: 118px; }
.profiles-top .manage-link { background: none; border: none; color: #fff; font-size: 1rem; display: flex; align-items: center; gap: 8px; }
.profiles-top .manage-link:hover { color: var(--red); }
.profiles-h1 { font-size: 2.4rem; margin: 0 0 40px; font-weight: 400; }
.profiles-grid { display: flex; gap: 5vw; flex-wrap: wrap; justify-content: center; }
.profile-tile { display: flex; flex-direction: column; align-items: center; gap: 14px; background: none; border: none; color: #fff; position: relative; }
.profile-avatar-lg {
  width: 130px; height: 130px; border-radius: 6px; display: flex; align-items: center; justify-content: center;
  font-size: 3.4rem; transition: border 0.2s; border: 3px solid transparent;
}
.profile-tile:hover .profile-avatar-lg { border-color: #fff; }
.profile-tile .pname { font-size: 1.1rem; color: #808080; }
.profile-tile:hover .pname { color: #fff; }
.profile-tile .pmenu { position: absolute; top: 4px; right: 4px; display: none; gap: 4px; }
.manage-mode .profile-tile .pmenu { display: flex; }
.pm-btn { width: 30px; height: 30px; border-radius: 50%; border: none; background: rgba(20,20,20,0.85); color: #fff; display: flex; align-items: center; justify-content: center; }
.pm-btn:hover { background: var(--red); }
.pm-btn svg { width: 15px; height: 15px; }
.rename-input { background: transparent; border: 2px solid #fff; color: #fff; font-size: 1.1rem; text-align: center; width: 150px; }
.add-profile { width: 130px; height: 130px; border-radius: 6px; border: 3px solid transparent; background: #2f2f2f; color: #fff;
  display: flex; align-items: center; justify-content: center; }
.add-profile:hover { border-color: #fff; }
.add-profile svg { width: 44px; height: 44px; }
.add-profile-form { position: fixed; inset: 0; z-index: 500; background: rgba(0,0,0,0.8); display: flex; align-items: center; justify-content: center; }
.add-profile-card { background: #181818; border-radius: 8px; padding: 30px 34px; width: 460px; max-width: 92vw; }
.add-profile-card h3 { margin: 0 0 18px; font-size: 1.3rem; }
.add-profile-card input[type=text] { width: 100%; padding: 12px; font-size: 1rem; background: #2f2f2f; border: 1px solid #555; color: #fff; margin-bottom: 16px; }
.avatar-choices { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 18px; }
.avatar-choice { width: 52px; height: 52px; border-radius: 6px; border: 3px solid transparent; cursor: pointer; display: flex; align-items: center; justify-content: center; font-size: 1.5rem; background: none; padding: 0; }
.avatar-choice.selected { border-color: #fff; }
.kids-toggle { display: flex; align-items: center; gap: 10px; margin-bottom: 18px; color: #e5e5e5; font-size: 0.95rem; }
.form-actions { display: flex; gap: 12px; justify-content: flex-end; }
.btn-cancel { background: none; border: 1px solid #555; color: #fff; padding: 10px 20px; }
.btn-cancel:hover { border-color: #fff; }
.btn-create { background: var(--red); border: none; color: #fff; padding: 10px 20px; }
.btn-create:hover { background: var(--red-hover); }

/* ===== Misc pages ===== */
.page-pad { padding-top: 68px; }
.section-head { padding: 30px 4vw 0; display: flex; align-items: center; gap: 16px; }
.section-head h1 { font-size: 2rem; margin: 0; }
.filter-select { background: transparent; border: 1px solid #595950; color: #fff; padding: 8px 12px; border-radius: 4px; font-size: 0.95rem; }
.filter-select option { background: #181818; }
.lang-panels { display: flex; gap: 24px; flex-wrap: wrap; margin: 8px 0 26px; }
.lang-panel { background: #2f2f2f; border-radius: 6px; padding: 18px 20px; flex: 1; min-width: 220px; }
.lang-panel h3 { margin: 0 0 10px; font-size: 1.05rem; font-weight: 500; }
.lang-panel .lp-sub { font-size: 0.8rem; color: #a3a3a3; margin-bottom: 10px; }
.coming-empty { padding: 26px 0; color: var(--text-muted); }
.new-card { flex: 0 0 auto; width: 240px; position: relative; cursor: pointer; }
.new-card img { width: 100%; aspect-ratio: 16/9; object-fit: cover; border-radius: 6px; }
.new-card .nc-label { position: absolute; left: 10px; bottom: 8px; background: var(--red); color: #fff; font-size: 0.75rem; padding: 2px 8px; border-radius: 2px; }
.new-card .nc-name { font-size: 0.9rem; margin-top: 8px; font-weight: 500; }
.new-card .nc-sub { font-size: 0.8rem; color: #a3a3a3; }
.text-search-card { flex: 0 0 auto; width: 260px; font-family: 'NetflixDisplay', sans-serif; font-size: 2rem; text-transform: uppercase; padding: 12px 0; cursor: pointer; line-height: 1.05; }
.text-search-card:hover { color: var(--red); }
.account-card { max-width: 640px; margin: 20px auto; background: #181818; border-radius: 6px; padding: 28px 32px; }
.account-card h2 { margin: 0 0 6px; }
.account-row { display: flex; justify-content: space-between; padding: 12px 0; border-bottom: 1px solid #2f2f2f; font-size: 0.95rem; }
.account-row:last-child { border-bottom: none; }
.footer { padding: 30px 4vw; color: #707070; font-size: 0.85rem; margin-top: 40px; }
@media (max-width: 900px) {
  .nf-nav { display: none; }
  .ep-row { grid-template-columns: 140px 24px 1fr; }
  .ep-dur { display: none; }
}
