    return () => clearTimeout(debounceRef.current)
  }, [query, searchOpen])

  const submitSearch = () => {
    const q = query.trim()
    if (!q) return
    setSearchOpen(false)
    setQuery('')
    nav(`/search?q=${encodeURIComponent(q)}`)
  }

  const closeAll = () => { setBellOpen(false); setMenuOpen(false) }

  return (
    <header className={`nf-header ${scrolled ? 'scrolled' : ''}`}>
